(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0025.js"] = [{"id":"glyph-seal-7b80","script":"seal","character":"简","reading":"jiǎn","description":"⒈不复杂，不烦琐，跟\"繁\"相对～单些。太～陋。～化。～明扼要。精兵～政。\n⒉轻忽，怠慢～慢。\n⒊盐，选择～拔。～选。\n⒋〈古〉用来写字的竹片或木片竹～。木～。〈引〉书信书～。来～。\n②〈方〉作\"索性\"讲天黑，雨又大，你～直别回去了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-简"},{"id":"glyph-seal-7b85","script":"seal","character":"箅","reading":"bì","description":"bì：〔～子〕有空隙而能起间隔作用的片状器具，如竹～～”、纱～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-箅"},{"id":"glyph-seal-7b93","script":"seal","character":"箓","reading":"lù","description":"箓（籾）lù\n⒈簿籍，册子图～。\n⒉道士搞所谓\"召神驱鬼\"、\"祈福消灾\"等迷信活动骗人钱财时所画的符号符～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-箓"},{"id":"glyph-seal-7b95","script":"seal","character":"箕","reading":"jī","description":"jī：(1)用竹篾、柳条或铁皮等制成的扬去糠麸或清除垃圾的器具（通常称簸箕”）～帚。\n(2)簸箕形的指纹，不成圆形斗（dǒu）～。\n(3)星名，二十八宿之一。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-箕"},{"id":"glyph-seal-7b97","script":"seal","character":"算","reading":"suàn","description":"suàn：核计，计数～草。～盘。～式。～账。～术。～计（ａ．算数目；ｂ．考虑；ｃ．估计；ｄ．暗中某划损害别人。计”均读轻声）。清～。预～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-算"},{"id":"glyph-seal-7ba1","script":"seal","character":"管","reading":"guǎn","description":"guǎn：(1)吹奏的乐器～乐器。～弦乐。\n(2)圆而细长中空的东西～道。～线。～见（谦辞，浅陋的见识）。～窥蠡测（从竹管里看天，用瓢量海水，喻眼光狭窄，见识短浅）。～中窥豹。气～。血～。针～。双～齐下。\n(3)形状像管的电子器件电子～。晶体～。\n(4)负责，经理～理。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-管"},{"id":"glyph-seal-7ba7","script":"seal","character":"箧","reading":"qiè","description":"小箱子,藏物之具。大曰箱,小曰箧","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-箧"},{"id":"glyph-seal-7baa","script":"seal","character":"箪","reading":"dān","description":"盛物件的小筐\n箪食\n箪 dān古代盛饭用的圆形竹器。\n【箪食壶浆】原指百姓用酒饭欢迎军队。现多形容正义之师受人民欢迎的情状。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-箪"},{"id":"glyph-seal-7bab","script":"seal","character":"箫","reading":"xiāo","description":"箫xiǎo 1.小竹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-箫"},{"id":"glyph-seal-7bac","script":"seal","character":"箬","reading":"ruò","description":"ruò：(1)一种竹子，叶大而宽，可编竹笠，又可用来包棕子～竹。～笠。～帽。～席。\n(2)箬竹的叶子。\n(3)笋皮。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-箬"},{"id":"glyph-seal-7bad","script":"seal","character":"箭","reading":"jiàn","description":"jiàn：(1)用弓发射到远处的兵器弓～。～镞。～头。～在弦上（喻事情已经到了不得不做或话已经到了不得不说的地步）。\n(2)箭能射到的距离一～之遥。～步。\n(3)形容急切、迅速归心似～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-箭"},{"id":"glyph-seal-7bb1","script":"seal","character":"箱","reading":"xiāng","description":"xiāng：(1)收藏衣物的方形器具，通常是上面有盖扣住～子。衣～。书～。药～。\n(2)像箱子的器具冰～。风～。信～。集装～。\n(3)同厢”⑤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-箱"},{"id":"glyph-seal-7bb4","script":"seal","character":"箴","reading":"zhēn","description":"zhēn：(1)同针”①。\n(2)劝告，劝戒～言。～规。～谏。\n(3)古代一种文体，以告诫规劝为主～铭（箴”是规戒性的韵文；铭”是刻在器物或碑石上兼于规戒、褒赞的韵文。因其作用有相似之处，故后人多连称）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-箴"},{"id":"glyph-seal-7bb8","script":"seal","character":"箸","reading":"zhù","description":"zhù：(1)筷子。\n(2)一种生在南海岸边沙中的竹子。\n(3)古同著”，明显。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-箸"},{"id":"glyph-seal-7bc1","script":"seal","character":"篁","reading":"huáng","description":"huáng：竹林，泛指竹子幽～。修～。～竹。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-篁"},{"id":"glyph-seal-7bc6","script":"seal","character":"篆","reading":"zhuàn","description":"zhuàn：(1)汉字的一种书体大～。小～。～体。～书。\n(2)书写篆字～额。\n(3)印章多用篆文，故为官印的代称，又为对别人名字的敬称～刻。摄～。次～。台～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-篆"},{"id":"glyph-seal-7bc7","script":"seal","character":"篇","reading":"piān","description":"piān：(1)首尾完成的文章或诗词～章。诗～。～目。～什（shí）（《诗经》中的雅”和颂”以十篇为一什”，所以诗章亦称篇什”）。～幅。长～大论。千～一律。\n(2)量词，指文章、纸张、书页一～论文。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-篇"},{"id":"glyph-seal-7bd3","script":"seal","character":"篓","reading":"lǒu","description":"用竹、藤、柳条等编成的盛物器具，如鱼篓、背篓。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-7bd9","script":"seal","character":"篙","reading":"gāo","description":"gāo：用竹竿或杉木等制成的撑船工具竹～。～工。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-篙"},{"id":"glyph-seal-7bdd","script":"seal","character":"篝","reading":"gōu","description":"gōu：竹笼～火。～灯。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-篝"},{"id":"glyph-seal-7be1","script":"seal","character":"篡","reading":"cuàn","description":"cuàn：(1)封建时代特指臣子夺取君位故得肆其奸慝，以成～盗之祸”。～位。\n(2)泛指夺取大长公主执囚青，欲杀之，其友公孙敖与壮士往～之”。～夺。～党。～国。～权。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-篡"},{"id":"glyph-seal-7be6","script":"seal","character":"篦","reading":"bì","description":"bì：(1)一种齿比梳子密的梳头用具，称篦子”。\n(2)以篦子梳～头。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-篦"},{"id":"glyph-seal-7bea","script":"seal","character":"篪","reading":"chí","description":"chí：(1)古书上说的一种竹。\n(2)古代一种用竹管制成像笛子一样的乐器，有八孔。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-篪"},{"id":"glyph-seal-7bee","script":"seal","character":"篮","reading":"lán","description":"篮球架上供投球用的带网的铁圈\n竹轿\n⒈用竹、藤、柳条、塑料带等编成的上有提梁的盛物器竹～子。提～买菜。\n⒉指一种体育用品及体育活动～球。～架。～网。投～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-篮"},{"id":"glyph-seal-7bfc","script":"seal","character":"篼","reading":"dōu","description":"dōu：盛东西用的竹器，亦有用藤或柳条做成的背～。\n〔～子〕走山路坐的竹轿，一般用竹椅捆在两根竹竿上做成。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-篼"},{"id":"glyph-seal-7c0b","script":"seal","character":"簋","reading":"guǐ","description":"guǐ：古代盛食物器具，圆口，双耳。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-簋"},{"id":"glyph-seal-7c1f","script":"seal","character":"簟","reading":"diàn","description":"diàn：(1)竹席竹～。～筧（车上的竹席篷）。\n(2)竹名～竹。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-簟"},{"id":"glyph-seal-7c27","script":"seal","character":"簧","reading":"huáng","description":"huáng：(1)乐器里用金属或其他材料制成的发声薄片～片。笙～。双～管。巧舌如～。\n(2)器物里有弹力的机件弹（tán）～。锁～。\n〔双～〕ａ．曲艺的一种；ｂ．喻一方出面，一方背后操纵的活动。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-簧"},{"id":"glyph-seal-7c2a","script":"seal","character":"簪","reading":"zān","description":"zān：(1)用来绾住头发的一种首饰，古代亦用以把帽子别在头发上～子。金～。玉～。～缨（做官者显贵之称）。～绅。\n(2)插，戴～戴。～菊。～笔（古人朝见，插笔于冠，以备记事）。～笏（古代笏以记事，簪笔以备写，臣僚奏事执笏簪笔。故亦称做官）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-簪"},{"id":"glyph-seal-7c38","script":"seal","character":"簸","reading":"bò；bǒ","description":"bò：〔～箕〕ａ．扬糠除秽、清理垃圾的器具，用竹篾、柳条或铁皮制成，三面有边沿，一面敞口；ｂ．簸箕形的指纹（箕”均读轻声）。\nbǒ：(1)用簸箕颠动米粮，扬去糠秕和灰尘～谷。\n(2)颠动摇晃颠～。～荡。～动。～弄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-簸"},{"id":"glyph-seal-7c40","script":"seal","character":"籀","reading":"zhòu","description":"zhòu：阅读～读（读书）。～绎（阅读并理出文章的脉络）。\n〔～文〕古代的一种字体。中国春秋战国时流行于秦国，今存石鼓文是其代表。亦称大篆”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-籀"},{"id":"glyph-seal-7c41","script":"seal","character":"籁","reading":"lài","description":"从孔穴中发出的声音。亦泛指一般的声响\n籁lài〈古〉一种三孔管乐器吹鸣～。〈引〉从孔穴中发出的声音。泛指声音万～俱寂。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-籁"},{"id":"glyph-seal-7c4d","script":"seal","character":"籍","reading":"jí","description":"jí：(1)书，书册古～。书～。经～。典～。\n(2)登记隶属关系的簿册；隶属关系～贯。户～。国～。学～。\n(3)登记～没（mò）。～吏民。\n(4)征收～田。\n(5)古代各种捐税的统称。\n〔～～〕ａ．形容纷扰很大；ｂ．形容名声很大；ｃ．形容纵横交错的样子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-籍"},{"id":"glyph-seal-7c73","script":"seal","character":"米","reading":"mǐ","description":"mǐ：(1)谷类或其他植物的子实去了皮的名称小～。大～。稻～。～珠薪桂（米像珍珠；柴像桂木，形容物价昂贵，生活困难）。\n(2)国际长度单位（旧称公尺”米突”），一米等于三市尺。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-米"},{"id":"glyph-seal-7c74","script":"seal","character":"籴","reading":"dí","description":"籴dí买进粮食。\n①买进谷物。\n②姓。春秋晋有大夫籴茷。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-籴"},{"id":"glyph-seal-7c7b","script":"seal","character":"类","reading":"lèi","description":"亦类此耳。\n⒈种，具有共同特征事物的综合同～。种～。分门别～。物伤其～。\n⒉似，像画虎～狗。刻鹄～鹜。\n⒊大抵，大致～多如斯。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-类"},{"id":"glyph-seal-7c89","script":"seal","character":"粉","reading":"fěn","description":"fěn：(1)细末儿～末。～剂。～尘。米～。花～。药～。漂白～。\n(2)特指化装用的粉末香～。～墨登场。～黛。扑～。～霜。\n(3)用涂料抹刷～刷。～饰。\n(4)使破碎，成为粉末～碎。～身碎骨。\n(5)白色的或带粉末的～墙。～蝶。～连纸。～笔。\n(6)用豆粉或别的粉做成的食品～丝。凉～。～皮。～芡（qiàn）。米～肉。\n(7)浅红色～色。～花。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粉"},{"id":"glyph-seal-7c92","script":"seal","character":"粒","reading":"lì","description":"lì：(1)成颗的东西，细小的固体米～。盐～。颗～。～子（ａ．成果的、细小的东西，子”读轻声；ｂ．指基本粒子”，物理学上指构成物体的最简单的物质）。\n(2)量词，多指颗粒状的东西一～米。一～珍珠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粒"},{"id":"glyph-seal-7c95","script":"seal","character":"粕","reading":"pò","description":"pò：米渣滓糟～（喻没有价值的东西）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粕"},{"id":"glyph-seal-7c97","script":"seal","character":"粗","reading":"cū","description":"cū：(1)疏忽，不周密～心。～疏。～略。～率（shuài）。\n(2)不精致，工料毛糙～糙。～劣。～料。～纸。～粮。～制滥造。去～取精。\n(3)长条东西直径大的～大。～壮。～重。～实。～线条（ａ．指毛道粗的线条ｂ．喻粗率的性格、作风，亦喻文章的粗略的构思）。～枝大叶。\n(4)颗粒大的～沙子。\n(5)声音低而大～哑。～声～气。\n(6)鲁莽～鲁。～暴。～野。～犷。～俗。～笨。～人。～手～脚。\n(7)略微～略。～具规模。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粗"},{"id":"glyph-seal-7c98","script":"seal","character":"粘","reading":"zhān","description":"zhān：(1)东西互相附着连结在一起糖～牙。\n(2)用胶或糨糊把一种东西胶合在另一种东西上～贴。～连。～接。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粘"},{"id":"glyph-seal-7c9c","script":"seal","character":"粜","reading":"tiào","description":"泛指出卖","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粜"},{"id":"glyph-seal-7c9f","script":"seal","character":"粟","reading":"sù","description":"sù：(1)一年生草本植物，子实为圆形或椭圆小粒。北方通称谷子”，去皮后称小米”～子。沧海一～。\n(2)古代泛称谷类重（zhòng）农贵～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粟"},{"id":"glyph-seal-7ca4","script":"seal","character":"粤","reading":"yuè","description":"yuè：(1)中国广东省的别称～语。～剧。\n(2)古同聿”、越”、曰”，文言助词，用于句首或句中。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粤"},{"id":"glyph-seal-7caa","script":"seal","character":"粪","reading":"fèn","description":"施肥\n屎,粪便\n⒈屎，大便～便。\n⒉施肥～地。～田。\n⒊扫除～除。\n【粪土】粪便和泥土。〈喻〉不值钱的东西，含有蔑视～土当年万户侯。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粪"},{"id":"glyph-seal-7cae","script":"seal","character":"粮","reading":"liáng","description":"桂馥曰谷也者,非古训。紌乃行者之干食。”\n多载资粮。\n引申指谷类;粮食\n⒈可吃的谷类、豆类等～食。干～。杂～。军～。民有余～。\n⒉农业税踊跃交公～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粮"},{"id":"glyph-seal-7cb1","script":"seal","character":"粱","reading":"liáng","description":"liáng：(1)粟的优良品种的总称一枕黄～。\n(2)精美的主食膏～（泛指美味的饭菜，如～～子弟”，旧时指达官贵人家的子弟）。～糗（粱制的干粮）。～肉。\n〔高～〕一年生草本植物，子实红褐色，可食，亦可酿酒、制淀粉。杆可用来编席、造纸等。亦称蜀黍”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粱"},{"id":"glyph-seal-7cb2","script":"seal","character":"粲","reading":"càn","description":"càn：(1)鲜明～烂（同灿烂”）。～～。～然。\n(2)美～者。～花（形容言谈之美）。\n(3)笑以博一～。\n(4)古称上等的米。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粲"},{"id":"glyph-seal-7cb3","script":"seal","character":"粳","reading":"jīng","description":"jīng：稻的一种，米粒宽而厚，近圆形，米质黏性强，胀性小～稻。～米。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粳"},{"id":"glyph-seal-7cb9","script":"seal","character":"粹","reading":"cuì","description":"cuì：(1)纯一，不杂纯～。～白。～而不杂。\n(2)精华国～（一国文化的精华）。文～。精～。\n(3)古同萃”，齐全，集聚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粹"},{"id":"glyph-seal-7cbc","script":"seal","character":"粼","reading":"lín","description":"lín：〔～～〕形容山石间水流清澈。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粼"},{"id":"glyph-seal-7cbd","script":"seal","character":"粽","reading":"zòng","description":"zòng：〔～子〕用箬叶或苇叶裹糯米做成的多角形的食品。亦称角黎”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粽"},{"id":"glyph-seal-7cbe","script":"seal","character":"精","reading":"jīng","description":"jīng：(1)上好的白米食不厌～”。\n(2)细密的，与粗”相对～密。～细。～确。～制。～读。～选。～心。～研。～雕细镂。\n(3)聪明，思想周密～悍。～敏。～明。\n(4)物质中最纯粹的部分，提炼出来的东西～华。～英。～神（ａ．指人主观世界，包括意识、思维活动和一般心理状态；ｂ．内容实质，主要的意义；ｃ．指人表现出来的活力）。\n(5)人表现出来的活力、生气～力。聚～会神。无～打采。\n(6)专一，深入～诚。～忠。～炼。～湛。～严。\n(7)雄性动物体内的生殖物质～子。\n(8)很、极～湿。～瘦。～光。\n(9)完美，最好～美。～妙。～益求～。\n(10)明朗，清明天～而见景星”。\n(11)神话传说中的妖怪～灵（ａ．鬼怪；ｂ．机灵）。妖～。\n(12)古同菁”，花。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-精"},{"id":"glyph-seal-7cc1","script":"seal","character":"糁","reading":"shēn；san","description":"米粒;饭粒\n散粒,碎粒\n以米和羹\n洒,散落\n涂抹;粘\n⒈〈方〉指煮熟的米粒。\n⒈谷类磨成的渣粒大米～儿。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糁"},{"id":"glyph-seal-7cca","script":"seal","character":"糊","reading":"hú；hū；hù","description":"hū：涂抹或粘合使封闭起来～了一层泥。\nhú：(1)粘合，涂附裱～。～墙。～窗户。\n(2)粥类～口。\n(3)同煳”。\n〔～涂〕ａ．不明事理；认识凝混乱，如他太～～了”；ｂ．内容混乱的，如～～账”。\nhù：(1)像粥一样的食物面～。辣椒～。\n(2)欺骗，蒙混，敷衍～弄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糊"},{"id":"glyph-seal-7ccd","script":"seal","character":"糍","reading":"cí","description":"cí：一种用江米（糯米）做成的食品～粑。～团。～糕。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糍"},{"id":"glyph-seal-7cd5","script":"seal","character":"糕","reading":"gāo","description":"gāo：用米粉或面粉搀和其他材料蒸制或烘烤而成的食品年～。蛋～。绿豆～。～点。～饼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糕"},{"id":"glyph-seal-7cd6","script":"seal","character":"糖","reading":"táng","description":"táng：(1)从甘蔗、甜菜、米、麦等提制出来的甜的物质白～§～。冰～。～浆。～稀。～膏。～瓜儿。～房（旧时制糖的作坊。亦称糖寮”、榨寮”）。～衣。\n(2)碳水化合物，有机化合物的一类，分为单糖”、双糖”三种，是人体内产生热能的主要物质～元。～尿病（因人体内胰岛素分泌不足所引起。是一种以体内糖代谢紊乱、血糖增高为主的慢性疾病）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糖"},{"id":"glyph-seal-7cd7","script":"seal","character":"糗","reading":"qiǔ","description":"qiǔ：(1)干粮，炒熟的米或面等。\n(2)饭或面食粘连成块状或糊状。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糗"},{"id":"glyph-seal-7cdc","script":"seal","character":"糜","reading":"mí；méi","description":"mí：(1)粥肉～。～沸（形容混乱纷扰）。\n(2)烂，碎～烂。～躯（牺牲生命）。～灭。\n(3)浪费～费。\n(4)姓。\nméi：不黏的黍（亦称穄”）～子。～黍。～子面。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糜"},{"id":"glyph-seal-7cdf","script":"seal","character":"糟","reading":"zāo","description":"zāo：(1)做酒剩下的渣子酒～。～粕（亦喻无价值的东西）。～蛋。～糠之妻（指贫穷时共患难的妻子）。\n(2)腐朽，腐烂～烂。～朽。\n(3)坏事情办～了。～糕。\n(4)作践，损害～蹋。～践（践”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糟"},{"id":"glyph-seal-7ce0","script":"seal","character":"糠","reading":"kāng","description":"kāng：(1)稻、麦、谷子等的子实所脱落的壳或皮米～。糟～。～秕。～醛（有机化合物，是制造塑料、合成纤维、合成橡胶、药物等的原料）。\n(2)萝卜等因失掉水分而中心呈蜂窝状。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糠"},{"id":"glyph-seal-7cef","script":"seal","character":"糯","reading":"nuò","description":"nuò：稻的一种，米黏性大～稻。～米（亦称江米”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糯"},{"id":"glyph-seal-7cfb","script":"seal","character":"系","reading":"xì；ji","description":"拴;系结\n约束;羁绊\n拘囚\n留意;挂念\n牵涉;关连\n⒈结，缚，扣～鞋带。\n⒉见xì。\n⒈有联属、有条理的～统。水～。世～。派～。一～列。\n⒉高等学校中按学科设置的教学单位哲学～。数学～。生物～。\n⒊是确～真情。\n⒋关联，联结关～。联～。\n⒍带子袜～。鞋～。\n⒎拴，绑，捆着送达～马。～绊其足。将车上的东西～着拿下来。〈引〉拘囚，拘束～狱。～于习俗。\n⒏挂，悬～念。群言～于口。\n⒐地层系统分类的第二级，比界小，相当于地质年代的纪。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-系"},{"id":"glyph-seal-7d0a","script":"seal","character":"紊","reading":"wěn","description":"wěn：乱～乱。有条不～。纲颓纪～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-紊"},{"id":"glyph-seal-7d20","script":"seal","character":"素","reading":"sù","description":"sù：(1)本色，白色～服。～丝。\n(2)颜色单纯，不艳丽～净。～淡。～妆。～雅。～描。\n(3)洁白的绢尺～（用绸子写的信）。\n(4)本来的，质朴、不加修饰的～质。～养。～性。～友（真诚淳朴的朋友）。\n(5)物的基本成分色～。毒～。维生～。\n(6)向来～来。～常。～志。平～。\n(7)白，不付代价～餐。\n(8)非肉类的食品，与荤”相对～食。～席。～油。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-素"},{"id":"glyph-seal-7d22","script":"seal","character":"索","reading":"suǒ","description":"suǒ：(1)大绳子或大链子～子。～道。钢～。绞～。线～。\n(2)搜寻，寻求～引。思～。搜～。探～。\n(3)讨取，要～还。～求。～取。勒～。\n(4)尽，毫无～然无味。\n(5)单独离群～居。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-索"},{"id":"glyph-seal-7d27","script":"seal","character":"紧","reading":"jǐn","description":"引申为物体受拉力或压力后呈现的紧张状态。同松”相对\n指经济不宽裕\n急促;迫切\n⒈紧，跟\"松\"相对。物体受拉力或压力之后的一种状态绑～。弦绷得太～。\n⒉收束把腰带～一～。\n⒊密切，靠得极近～邻。～接。～挨着。\n⒋急迫，短促，不宽裕时间～。功课～。工作～。过几年～日子。〈引〉因时间紧迫而加快抓～工作，手～点，可以提前完成任务。\n⒌事情严重或关系重大～要关头。～急事件。\n①激烈，迫切，不松弛工作～张。形势～张。\n②供应不足，难以应付市场～张。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-紧"},{"id":"glyph-seal-7d2b","script":"seal","character":"紫","reading":"zǐ","description":"zǐ：(1)在可见光中波长最短，红与蓝合成的颜色～红。～铜。～外线。～药水。\n(2)道教和某些朝代的统治者所崇尚的色彩，因而常在其宫室、服饰、用物前冠之以紫”～衣。～书（a.道经；b.皇帝诏书）。～诰（帝王诏令）。～台（神仙、帝王所居）。～气（祥瑞之气，多附会为帝王、圣贤或宝物出现的先兆）。～绶。～垣（皇宫）。～阙。～光阁。～禁城。～袍金带。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-紫"},{"id":"glyph-seal-7d2f","script":"seal","character":"累","reading":"lèi；léi；lěi","description":"léi：〔～～〕a.连续成串，如果实～～”；b.颓丧的样子，如～～若丧家之犬”。\n〔～赘〕a.多余，不简洁，如文字～～”；b.使人感到多余或麻烦的事物，如负重登高，不胜～～”（赘”均读轻声）。\n乏；\nlěi：(1)连续，重叠，堆积～计。～日。～积。～～。日积月～。连篇～牍。\n(2)照原数目多少而递增～进税。\n(3)连及，连带～及。牵～。拖～。\n乏；\nlèi：(1)疲乏，过劳劳～。～乏。\n(2)使疲劳病刚好，别再～着。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-累"},{"id":"glyph-seal-7d6e","script":"seal","character":"絮","reading":"xù","description":"xù：(1)棉花的纤维棉～。被～。\n(2)古代指丝的纤维，特指熟丝。\n(3)像棉絮的东西花～。芦～。柳～。\n(4)在衣被等物里铺棉花、丝绵等～被子。～棉袄。\n(5)连续重复，惹人厌烦～叨。～烦。～聒。～～叨叨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-絮"},{"id":"glyph-seal-7da6","script":"seal","character":"綦","reading":"qí","description":"qí：(1)青黑色～巾。\n(2)极，很～难。～切。言之～详。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-綦"},{"id":"glyph-seal-7dae","script":"seal","character":"綮","reading":"qǐ；qìng","description":"qìng：筋骨结合处；比喻事物的关键。\n〔肯～〕见肯”。\nqǐ：古同??”，古代官吏出行用作符信的戟衣。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-綮"},{"id":"glyph-seal-7e20","script":"seal","character":"縠","reading":"xiá","description":"縠xiá 1.鞋。一说履跟后帖。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-縠"},{"id":"glyph-seal-7e3b","script":"seal","character":"縻","reading":"mí","description":"mí：(1)牛缰线。\n(2)捆，拴羁～（a.束缚；b.笼络使不生异心）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-縻"},{"id":"glyph-seal-7e41","script":"seal","character":"繁","reading":"fán；pó","description":"fán：(1)复杂～杂。～乱。删～就简。～难。～嚣。\n(2)多～多。～重（zhòng）。纷～。频～。～星。～忙。～芜。～博。\n(3)兴盛～茂。～荣。～华。\n(4)生物增生新个体～殖。～育。～衍。\n简；\npó：姓。\n〔～台〕中国河南省开封市东南的古迹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-繁"},{"id":"glyph-seal-7e47","script":"seal","character":"繇","reading":"yáo；yóu；zhòu","description":"yáo：(1)同徭”。\n(2)古同谣”，歌谣。\nyóu：古同由”，从，自。\nzhòu：古同籀”，占卜的文辞。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-繇"},{"id":"glyph-seal-7e82","script":"seal","character":"纂","reading":"zuǎn","description":"zuǎn：(1)搜集材料编书～修（a.编纂，亦指做这方面工作的人；b.继承并加强修养、治理）。～绣（编织和刺绣）。～辑。编～。\n(2)古代指红色或彩色丝带。\n(3)妇女梳在头后边的发髻～儿。\n(4)古同缵”，继承。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纂"},{"id":"glyph-seal-7ea0","script":"seal","character":"纠","reading":"jiū","description":"缠绕\n⒈绳子。〈引〉缠绕～缠。\n⒊矫正，改过来～偏。～正。有错必～。\n①争执调解～纷。\n②杂乱交错～纷。\n纠jiǎo 1.见\"窈纠\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纠"},{"id":"glyph-seal-7ea1","script":"seal","character":"纡","reading":"yū","description":"萦绕回旋\n纡yū屈曲，绕弯～回。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纡"},{"id":"glyph-seal-7ea2","script":"seal","character":"红","reading":"hóng","description":"后也指各种红色\n⒉见hóng。\n⒈赤，像火，鲜血那样的颜色～色。～花。火～。〈转义〉\n①革命的～军来了。～色娘子军。\n②喜庆操办～事。\n③光荣上～榜。\n④顺利，成功等～起来了。开门～。\n⑤先进的，众人尊敬的～旗手。～管家。\n⒉受宠信的人～人。\n⒊额外的利润～利。分～。\n①人世间。\n②繁华热闹的地方。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-红"},{"id":"glyph-seal-7ea3","script":"seal","character":"纣","reading":"zhòu","description":"驾车马后部的革带\n商代最末的君主名,史称纣王\n⒈驾车时系在牲口后的皮带子。\n⒉〈古〉人名。商朝末代君主。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纣"},{"id":"glyph-seal-7ea4","script":"seal","character":"纤","reading":"xiān；qian","description":"用于拉船的绳索\n牵牲口的绳索\n⒈拉船的绳子～绳。揹～。\n①拉着纤绳使船前进。\n②旧指介绍买卖产业从中取利。\n纤jiān 1.刺。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纤"},{"id":"glyph-seal-7ea5","script":"seal","character":"纥","reading":"gē","description":"下等丝\n回纥\n⒉见hé；jié。\n⒉见gē、jié。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纥"},{"id":"glyph-seal-7ea6","script":"seal","character":"约","reading":"yuē","description":"共同商定的事,共同议定要遵守的条文\n盟约;相期的诺言\n缠束;环束\n⒈〈古〉套，捆缚～车。～紧。\n⒉拘束，限制～束。制～。\n⒊共同议定的要遵守的条款定～。条～。订～。公～。\n⒋商定或预先说定的事预～。如～。失～。\n⒌请～她来。特～。\n⒍简明，简要简～。\n⒎节俭节～。俭～。\n⒏大概～计。大～。\n⒐数学上指简化分数，即用公因数去除分子和分母4/8可～为1/2。\n⒈称重量把这袋米～一～，多少斤？\n约yào 1.总要;纲要。\n约dì 1.琴上圆形的星徽。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-约"},{"id":"glyph-seal-7ea7","script":"seal","character":"级","reading":"jí","description":"引申为等级,特指官阶爵位的品级\n石阶\n乃领宾者延之而\n⒈等次等～。下～。高～。提～。降～。\n⒊台阶石～。\n⒌颗，〈古〉指斩下的人头首～。斩虏数百～。\n级zhuì 1.缵列。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-级"},{"id":"glyph-seal-7ea8","script":"seal","character":"纨","reading":"wán","description":"细致洁白的薄绸\n纨扇,细绢扇\n幼小的\n⒈细绢，细致的丝织品～扇。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纨"},{"id":"glyph-seal-7eaa","script":"seal","character":"纪","reading":"jì","description":"开端,头绪\n要领\n纪jǐ姓。\n⒈丝的头绪丝缕有～。\n⒉记载～事。～要。～传。\n⒊记年单位\n①〈古〉十二年为一～。\n②公历以一百年为一世～。\n⒋年龄，岁数年～。\n⒌准则，制度师行有～。党～国法。加强～律。\n①法度国有～纲。\n②治理～纲其国。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纪"},{"id":"glyph-seal-7eab","script":"seal","character":"纫","reading":"rèn","description":"缝纫; 缝补\n连缀,联结\n⒈引线穿针～针。\n⒉缝补缝～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纫"},{"id":"glyph-seal-7eac","script":"seal","character":"纬","reading":"wěi","description":"缠捆,系束\n组织\n治理\n纬纱;织物的横丝\n东西向的道路或土地。与南北向的经”相\n⒈纬线，织布时使用梭子穿织的横纱或编织物的横线。\n⒉地理学上假设的与赤道平行之线。从赤道向北的称\"北纬\"，从赤道向南的称\"南纬\"，由赤道至南极或北极各为九十度。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纬"},{"id":"glyph-seal-7eaf","script":"seal","character":"纯","reading":"chún","description":"同一颜色的丝织品\n纯正,纯粹\n②纯净；不含杂质～天然食物。\n③纯粹；单一～黄。\n④纯熟工夫不～。\n【纯电感电路】除交变电源外，只含有电感元件的电路。电感两端的电压与电流同频，但电压比电流的相位超前π／z。线圈不消耗能量。\n【纯电容电路】除交变电源外，只含有电容元件的电路，在纯电容电路中，电容两端的电压与电流同频，但电压比电流的相位落后π／z。电容不消耗能量。\n【纯电阻电路】除交变电源外，只有电阻元件的电路，或有电感和电容元件，但它们对电路的影响可忽略。电压与电流同频且同相位。电阻将从电源获得的能量全部转变成内能\n【纯合体】基因型完全处于同质结合状态的生物体。如aa、aabb等基因型的生物。它们的自交后代是相对一致的，不会发生分离现象。\n【纯碱】见【碳酸钠】。\n【纯碱工业】以食盐、氨、水和二氧化碳为原料，以吸氨塔、碳酸化塔和滤碱机为主要设备制取纯碱的工业设施。\n【纯净物】只由一种单质或化合物所组成的物质，纯净物可分为单质和化合物两类。通常所指的纯净物是指含杂质少，具有一定纯度的物质。\n【纯利】总收支除去一切耗费后剩余的利润。\n【纯律】、音～音律的一种。根据自然之和弦制订。即在纯五度之间加入第五个泛音，使其成为自然之和弦，并顺次来确定音阶中各音的高度。纯律中基本音级间的音高关系，","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纯"},{"id":"glyph-seal-7eb0","script":"seal","character":"纰","reading":"pī；pí","description":"pī：布帛丝线松散；引申指疏漏，如纰漏。pí：在衣冠边缘加饰。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-7eb2","script":"seal","character":"纲","reading":"gāng","description":"事物的关键部分,事理的要\n⒈鱼网上的总绳网之～。〈引〉事物的关键部分～要。提～挈领。～举目张。\n⒉唐、宋时代成批运输货物的编组，每批的车辆、船只计数编号叫做\"一纲\"茶～。花石～。生辰～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纲"},{"id":"glyph-seal-7eb3","script":"seal","character":"纳","reading":"nà","description":"收藏;收入\n纳”假借为接纳”;接受\n⒈收进，接收～入。接～。吐故～新。\n⒉接受采～。\n⒊缴付～税。～公粮。\n⒋享受～凉。～福。\n⒌缝补～鞋底。补补～ ～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纳"},{"id":"glyph-seal-7eb4","script":"seal","character":"纴","reading":"rèn","description":"纴（絭）rèn绕线。泛指纺织～织。织～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纴"},{"id":"glyph-seal-7eb5","script":"seal","character":"纵","reading":"zòng","description":"南北称纵,东西称横。古作从衡”\n跟物体的长的一边平行的\n广泛\n谈道之余,纵言及文辞,…,非凡子\n⒈发，放～兵。～火。～虎归山。\n⒉放任，无拘束～容。放～。～情歌唱。\n⒊放开，释放～目远望。七擒七～。\n⒋身体猛然向前或向上～身跳过去。\n⒌即使～使。～有困难，也能克服。\n⒍竖，直，南北的方向，跟\"横\"相对～线。～剖。站成～队。\n⒎深广，从前到后的～深。\n⒏起皱纹纸揉～了。\n①引身，举身。\n②行动放肆。\n纵zǒng 1.见\"纵纵\"。 2.通\"总\"。掌握;统率。 3.通\"总\"。古代的一种丝织品。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纵"},{"id":"glyph-seal-7eb6","script":"seal","character":"纶","reading":"lún；guan","description":"用青丝带做的头巾\n昆布\n⒈青丝带。\n⒉见lún。\n⒈钓鱼用的丝线。\n⒉丝织的带子。\n⒊现用于一些合成纤维的名称涤～。锦～。棉～混纺。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纶"},{"id":"glyph-seal-7eb7","script":"seal","character":"纷","reading":"fēn","description":"旗上的飘带\n花边\n祸乱;灾难\n争执;纠纷\n⒈众多，杂乱～至沓来。～杂的声音。～乱的人群。\n①人或事物接二连三地～ ～响应献血。\n②既多又杂乱议论～ ～。落叶～ ～。\n⒉争执～争。排难解～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纷"},{"id":"glyph-seal-7eb8","script":"seal","character":"纸","reading":"zhǐ","description":"冥钱,旧俗为祭奠鬼神而焚化的纸钱\n进。\n⒉量词一～空文。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纸"},{"id":"glyph-seal-7eba","script":"seal","character":"纺","reading":"fǎng","description":"通绷”。捆绑,悬挂;束缚\n绸属;素纱\n⒈将丝、棉、麻、毛、化工纤维等制成纱或线～细纱。～毛线。\n⒉质地比绸子轻薄的丝织物或绸子的一种～绸。蜀～。\n纺bǎng 1.悬空绑着;捆缚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纺"},{"id":"glyph-seal-7ebd","script":"seal","character":"纽","reading":"niǔ","description":"比喻事物的根本,关键\n纽绊。器物上用以提携或系绳带的部件\n钮扣\n⒈器物上可以提起来或系挂的部分秤～。印～。\n⒉扣合衣物的东西～扣子。塑料～扣。\n⒊系结用的带子。〈喻〉连结、根本或关键～带。枢～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纽"},{"id":"glyph-seal-7ebe","script":"seal","character":"纾","reading":"shū","description":"宽缓;宽松\n解除;排除\n众谓予一\n⒈缓，延缓稍～。\n⒉解除，排除～难。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纾"},{"id":"glyph-seal-7ebf","script":"seal","character":"线","reading":"xiàn","description":"细长如线的东西\n线索\n⒈棉、麻、丝、毛、锦纶或金属等制成的细长东西棉～。丝～。毛～。电～。尼龙～。\n⒉像线的光～§外～〗～。铁道～。\n⒊细微，极少一～希望。\n⒋几何学上称只有长度而没有宽度和厚度的直～。曲～。\n⒌边缘交界处防～。火～。岸～。国境～。〈喻〉所接近的某种边际生命～。死亡～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-线"},{"id":"glyph-seal-7ec0","script":"seal","character":"绀","reading":"gàn","description":"红青,微带红的黑色\n绀青\n绀gàn黑带微红的颜色紫～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绀"},{"id":"glyph-seal-7ec1","script":"seal","character":"绁","reading":"xiè","description":"绳索\n牵引牲畜的绳索\n系、拴或捆绑\n⒈牵牲口的绳子或缚罪人的绳索马～。缧～。\n⒉捆绑。\n绁yì 1.超越。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绁"},{"id":"glyph-seal-7ec3","script":"seal","character":"练","reading":"liàn","description":"练习;操演\n漂洗;洗涤\n⒈白色的熟绢江平如～。\n⒉把丝麻或织品煮得柔软而洁白。\n⒋反复学习，再三操作～习。～基本功。～技术。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-练"},{"id":"glyph-seal-7ec4","script":"seal","character":"组","reading":"zǔ","description":"⒈〈古〉丝带，编织织～。素丝～之。\n⒉结合，构成～合。～成。\n⒊若干人结合成的单位学习～。科研～。\n⒋有规律、有系统的，合为一体的～词。～歌。～画。\n⒌量词两～铅笔。\n①有目的、有秩序、有系统的结合起来～织春节晚会。\n②按一定的任务、目的建立起来的集体党～织。体育～织。\n③事物的组成系统或各部分之间的关系～织庞大。～织关系。\n④多细胞动、植物体中构成器官的基本单位上皮～织。肌肉～织。\n⑤纺织品经纬的结构这是斜纹～织的布。那是平纹～织的布。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-组"},{"id":"glyph-seal-7ec5","script":"seal","character":"绅","reading":"shēn","description":"旧指地\n⒈〈古〉士大夫系的大带子，也指束带佩～。～之束之。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绅"},{"id":"glyph-seal-7ec6","script":"seal","character":"细","reading":"xì","description":"纤细⊥粗”相\n⒈微，小，跟\"大\"、\"巨\"、\"粗\"等相对～微。～小。～末。～声。～铁丝。～石沙。\n⒉精致～致。精～。景德镇～瓷。\n⒊周密～密。仔～。大胆心～。精打～算。～心观察。\n⒋详～说。详～。\n⒌微小的，具体的事无巨～。注意～节。\n⒍一点一滴，俭朴～水长流。他们过日子很～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-细"},{"id":"glyph-seal-7ec7","script":"seal","character":"织","reading":"zhī","description":"织zhì 1.用染丝织成的丝织品。 2.通\"帜\"。旗帜;标志。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-织"},{"id":"glyph-seal-7ec8","script":"seal","character":"终","reading":"zhōng","description":"终了;结束。与始”相对\n⒈末了，完了，结束，跟\"始\"相对～了。～点。～止。剧～。〈引〉死，生命完结寿～。\n⒉毕竟，到底～归。～于。～究。～见成效。\n①久远，永远。\n②经常。\n③往昔，自古以来。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-终"},{"id":"glyph-seal-7ec9","script":"seal","character":"绉","reading":"zhòu","description":"细葛布\n织出皱纹的丝织品","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绉"},{"id":"glyph-seal-7eca","script":"seal","character":"绊","reading":"bàn","description":"羁绊;拘束;束缚\n用绳子把足系住\n走路或跑步时被别的东西挡住或缠住\n绊 bàn 挡住或缠住，使其跌倒或行走不方便～倒、～手～脚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绊"},{"id":"glyph-seal-7ecc","script":"seal","character":"绌","reading":"chù","description":"不足\n绌 〈动〉\n通诎”。屈服;制服\n通黜”。废除;贬退\n世子学老子者则绌儒学,儒\n绌 chù不足；不够相形见～。\n⒈不足，不够钱已～。相形见～。\n⒉〈古〉通\"黜\"废～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绌"},{"id":"glyph-seal-7ecd","script":"seal","character":"绍","reading":"shào","description":"介绍,为人引见,使相互认识\n绍我周王见休。\n⒈继续，接续～述。～世而起。\n⒉联系～介。介～。\n绍chāo 1.缓慢。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绍"},{"id":"glyph-seal-7ece","script":"seal","character":"绎","reading":"yì","description":"引出头绪,寻求事理\n陈述\n陈列\n继续,连续不断","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绎"},{"id":"glyph-seal-7ecf","script":"seal","character":"经","reading":"jīng","description":"渭水支流。有南、北二源。北源出宁夏六盘山东麓固原县;南源出甘肃省华亭县,至平凉县境合流后,又东南流入陕西省,至高陵县入渭河 。如泾渭分明\n古州名\n县名\n⒈织布的纵线叫\"经\"，横线叫\"纬\"。\n⒉地面上东与西距离的度数称\"经度\"。地理上假定通过南极、北极同赤道成直角的线，以英国格林尼治天文台原址的子午线为起点，以东叫\"东经\"，以西叫\"西经\"，东、西各一\n百八十度。\n⒋具有典范性的～典。\n⒌宗教中宣讲教义的书佛～。圣～。古兰～。\n⒎禁受，承受，忍受～受。饱～风霜。\n⒏〈表〉过去而且已完成～历。曾～。已～。身～百战。\n⒐通过，路过～手。～过。途～西安。\n⒑中医把人体气血运行的主干叫\"经\"～脉。～络。\n⒒妇女的月经～期。\n⒓上吊，缢死自～。～其颈于树枝。\n①经营，管理擅长～纪。\n②经纪人，为买卖双方撮合，从中获取佣金的人。\n①社会生产关系的总合，也是政治和思想意识等上层建筑的基础，即经济基础。\n②国民经济的总称或指国民经济的某个部门～济状况。工业～济。\n③节约，便宜，化费少～济实惠。\n④收支状况～济宽裕。\n①从实践得来的知识或技能。\n②经历。\n经jìng 1.谓织布前，于机杼上绷齐并梳整纱缕，使成为经线。 2.通\"径\"。直径。 3.通\"径\"。小路。 4.通\"径\"。直。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-经"},{"id":"glyph-seal-7ed3","script":"seal","character":"结","reading":"jié","description":"植物生长果实\n坚硬;牢固\n健壮\n用绳、线、皮条等绾成的疙瘩\n旧时向官府承担责任或承认了结的书面的字据\n关键\n被联结的状态\n通髻”。总发,挽发而结之于顶\n⒈系，编织，扎缚打～。～绳。～毛衣。张灯～彩。〈引〉问题所在处症～。又指编结成的东西活～←蝶～。\n⒉聚，凝聚水已～冰。～晶体。\n⒊合，联合～合。～社。～交。\n⒋了毕，收束～业。～束。～账。\n⒌作为保证的一种字据具～。\n①各个组成部分的相互排列搭配 文章～构。经济～构。\n②建筑物上承担重力的构造砖木～构。\n③内部构造组织～构。机器～构。\n①植物长成所结的果实。\n②事情的终了或发展到一定阶段那件事已有了～果。\n③旧小说中指将人杀死～果了那厮的性命。\n⒔见jiē。\n⒈植物长果实或种子这棵梨树，今年刚～果。\n①植物长果实或种子。\n②坚固，牢靠这堵墙挺～实。\n③健壮他虽老，但身体很～实。\n⒋见jié。\n结成。\"执雠\"。\n⑾ 朋友;至交。\n⑿殷代的世家大族。\n结jì 1.发髻。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-结"},{"id":"glyph-seal-7ed4","script":"seal","character":"绔","reading":"kù","description":"绊络\n⒈同\"裤\"。\n⒉〈古〉套裤。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绔"},{"id":"glyph-seal-7ed5","script":"seal","character":"绕","reading":"rào","description":"环绕\n迂回绕过\n⒈缠～线。\n⒉纠缠，弄迷糊把他～住。这两个字总算将他～着了。\n⒊围着转～场一周。月亮～地球运行。\n⒋走弯路或迂回的路～了一段路。～到敌人背后。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绕"},{"id":"glyph-seal-7ed8","script":"seal","character":"绘","reading":"huì","description":"绘画\n用言辞形容","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绘"},{"id":"glyph-seal-7ed9","script":"seal","character":"给","reading":"gěi","description":"使对方得到或遭受到\n让;使;叫\n表示对象、目的,相当于为”、替”\n给伤员包扎\n引进动作行为的主动者,或表示被动语态,相当于被”\n表示方向,相当于朝”、对”、向”\n⒈交，付，送与请～我一支笔。〈引〉将动作或态度加于对方～他一巴掌。\n⒉介词。\n①替，为～人民办好事。\n②被，遭受～水冲走了。\n⒊助词。\n②〈方〉走时随手～门关好。\n⒋见jǐ。\n⒈供应～养。供～。自～自足。\n⒉富裕，丰足百姓充～。人～家足。\n⒊见gěi。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-给"},{"id":"glyph-seal-7eda","script":"seal","character":"绚","reading":"xuàn","description":"通侚”。迅疾的样子\n辉映;照耀\n点缀\n绚xuàn有文彩，色彩华丽～丽。～烂。素章增～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绚"},{"id":"glyph-seal-7edb","script":"seal","character":"绛","reading":"jiàng","description":"染为绛色\n古都名。春秋晋地\n绛jiàng深红色。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绛"},{"id":"glyph-seal-7edc","script":"seal","character":"络","reading":"luò","description":"⒈网状的东西。用于一些口语丝瓜～。\n①线绳结成的网状袋子用塑料～子装洗脸盆。\n②绕线、绕纱等的器具。\n⒈网状的东西脉～。经～。丝瓜～。\n⒉罩住头上～着发网。\n⒊缠绕，缠裹，环绕～线。笼山～野。\n⒋拉拢笼～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-络"},{"id":"glyph-seal-7edd","script":"seal","character":"绝","reading":"jué","description":"引申为断,断绝\n以绝秦望。\n秦王惊,自引而起,袖\n⒈断，隔断～交。～缘体。\n⒉完，完全，穷尽气～。～无例外。～处逢生。敌人陷入～境。\n⒊极，非常～密。～伦。～妙。～大多数。～无仅有。〈引〉高超，独特～技。～招。\n⒋一定，无论如何～不允许贪赃枉法。\n①极端，非常～顶的聪明。\n②最高峰泰山～顶。会当凌～顶。\n①最，极～对可靠。\n②完全，一定～对办得好。\n③无条件的，不受任何限制的～对存在于相对之中，在相对中有～对。\n④只根据一个条件测算的～对温度。～对高度。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绝"},{"id":"glyph-seal-7ede","script":"seal","character":"绞","reading":"jiǎo","description":"缠绕\n⒈拧合，扭紧～手巾。～棕绳。\n⒉用绳把人勒死或吊死的一种酷刑～刑。～架。\n⒊量词两～毛线。三～细纱。\n绞xiáo 1.苍黄色。 2.借指苍黄色单衣。 3.古代丧礼中敛尸用的束带。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绞"},{"id":"glyph-seal-7edf","script":"seal","character":"统","reading":"tǒng","description":"世代相继的系统\n纲纪,准则\n鞋袜等的筒状部分\n⒈丝的头绪抽其～。\n⒉事物的连续或彼此相连的关系系～。传～。血～。\n⒊纲要，纲领不知其～。\n⒋总括，综合，全面地～计。～筹。～理。\n⒍主管，率领～管。～辖。～兵百万。\n①部分结合成整体，分歧趋于一致全国～一。意见～一。\n②一致的，单一的～一认识。～一领导。\n①凭借政权来控制、治理国家或地区。\n②占绝对优势，支配控制别的事物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-统"},{"id":"glyph-seal-7ee0","script":"seal","character":"绠","reading":"gěng","description":"轮辐近轴处向外突出的部分\n泛指绳索\n绠短汲深\n绠bǐng 1.古时轮辐近轴处的突出部分。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绠"},{"id":"glyph-seal-7ee1","script":"seal","character":"绡","reading":"xiāo","description":"绡xiāo生丝，也指薄的生丝纺织品。\n绡shāo 1.船上挂帆的木柱。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绡"},{"id":"glyph-seal-7ee2","script":"seal","character":"绢","reading":"juàn","description":"麦青色的丝织物\n丝织品的通称\n手绢\n⒈一种薄的生丝织品，〈古〉多用作于书画、装璜等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绢"},{"id":"glyph-seal-7ee3","script":"seal","character":"绣","reading":"xiù","description":"著我绣夹裙。\n朝绣夹裙。\n⒈用彩色的丝线、棉线等在布、绸等上面刺成花纹、图象、文字等刺～。～花。～图。～字。\n⒉刺绣品苏～。湘～。蜀～。绒～。〈引〉华丽，精美，漂亮花梁～柱。～羽衔花他自得。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绣"},{"id":"glyph-seal-7ee5","script":"seal","character":"绥","reading":"suí","description":"上古五服之一\n⒉安，安抚～靖。\n绥suī 1.挽以登车的绳索。 2.安;安抚。 3.缚系。 4.告。 5.退军。 6.止住。 7.祭名。参见\"绥祭\"。 8.旧绥远省略称。1954年撤销，并入内蒙古自治区。\n绥ruí 1.古代旌旗的一种。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绥"},{"id":"glyph-seal-7ee6","script":"seal","character":"绦","reading":"tāo","description":"⒈用丝线编织成的带子或绳子，用以装饰衣物～子。～带。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绦"},{"id":"glyph-seal-7ee7","script":"seal","character":"继","reading":"jì","description":"继承","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-继"},{"id":"glyph-seal-7ee8","script":"seal","character":"绨","reading":"tí","description":"绨〈名〉\n丝织物类名\n绨tí〈古〉一种厚实而光滑的丝织品～袍。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绨"},{"id":"glyph-seal-7ee9","script":"seal","character":"绩","reading":"jì","description":"把麻纤维披开接续起来搓成线\n承继\n成就;功业\n庶绩\n⒈缉线，将麻搓成绳或线纺～。\n⒉功业，成果业～。巨大成～。战～辉煌。丰功伟～。\n绩jī 1.功业。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绩"},{"id":"glyph-seal-7eea","script":"seal","character":"绪","reading":"xù","description":"头绪,开端\n情绪,心情\n⒈丝头。〈喻〉开端头～。论端究～。\n⒉世系，事业先～。续未竟之～。\n⒊心情、思想等心～。情～。思～。意～。\n⒋残余的～余。～风。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绪"},{"id":"glyph-seal-7eeb","script":"seal","character":"绫","reading":"líng","description":"细薄而有花纹的丝织品,一面光,像缎子\n现代丝织品名。采用斜纹组织或以斜纹为底的提花组织,以桑蚕丝或与人造丝交织而成\n绫líng一种很薄而一面光滑的丝织物，可有花纹素广～。～罗绸缎。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绫"},{"id":"glyph-seal-7eed","script":"seal","character":"续","reading":"xù","description":"继续\n⒈连接，接上一段～假。～编。断长～短。\n⒉连接不断连～。继～。延～。\n⒊继承～祖。\n⒋添加将茶～上。肉汤里再～些水。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-续"},{"id":"glyph-seal-7eee","script":"seal","character":"绮","reading":"qǐ","description":"紫绮为上襦。\n光彩\n⒈有花纹的丝织品罗～。\n⒉美丽，华丽，～丽。华～。〈引〉珍贵雕盘～食会众客。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绮"},{"id":"glyph-seal-7eef","script":"seal","character":"绯","reading":"fēi","description":"红色,深红色\n绯 fēi红色～红。～衣。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绯"},{"id":"glyph-seal-7ef0","script":"seal","character":"绰","reading":"chuō","description":"姿态柔美\n隐隐约约\n端正\n吹拂\n搅乱\n①抓取顺手～起棍子。\n②同'焯'。又见chuò\n绰 chuò富足宽～。又见chāo。\n【绰绰有余】形容很宽绰，用不完。\n【绰号】外号。\n【绰约】形容女子体态柔美的样子。\n⒈匆忙抓起～起木凳。\n⒉通\"焯\"～波菜。\n⒈宽裕，舒缓宽～。～有余裕。～ ～有余。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绰"},{"id":"glyph-seal-7ef2","script":"seal","character":"绲","reading":"gǔn","description":"织成的带子\n通衮”\n帝王及公侯的礼服\n衮职,三公之职\n通昆”◇代子孙\n用带子保护、加强或装饰\n⒈绳。\n⒉编织成的带子。\n⒊绲边儿，沿着衣服等的边缘缝上布条或带子。\n绲hùn 1.混同。 2.绲戎，古西戎之一。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绲"},{"id":"glyph-seal-7ef3","script":"seal","character":"绳","reading":"shéng","description":"⒈由两股或两股以上的棉、麻、棕、草、金属丝、化学纤维等拧成的条状物～索。棕～子。尼龙～。\n⒉木工用的墨线～墨。〈喻〉标准，规矩，法则，法度有～可依。\n⒊制裁，约束～之以法。\n绳mǐn 1.见\"绳绳\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绳"},{"id":"glyph-seal-7ef4","script":"seal","character":"维","reading":"wéi","description":"隅,角落\n⒉系，连结～系。\n⒊保持，保全，保护～持。～护。\n⒌通\"惟\"。思考～万世之安。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-维"},{"id":"glyph-seal-7ef5","script":"seal","character":"绵","reading":"mián","description":"同义\n通棉”\n丝絮状物\n隋堤上,曾见几番,拂水\n⒈蚕丝结成的片或团丝～。\n⒊连续不断～延。～地千里。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绵"},{"id":"glyph-seal-7ef6","script":"seal","character":"绶","reading":"shòu","description":"绶shòu丝带。〈古〉用来拴玉、印或帷幕印～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绶"},{"id":"glyph-seal-7ef7","script":"seal","character":"绷","reading":"bēng","description":"缠束;包扎\n张紧,在两端或边上用力造成平直的坚挺状态\n猛地弹起\n稀疏地缝住或用针别上\n勉强支持;硬撑\n①拉紧；紧张不要把弦～得太紧了。\n①不舒展～着脸。\n②勉强支撑～住劲往下讲。又见bēng；bèng。\n①裂开～了一道口子。\n②用在'硬、直、亮'一类形容词的前面，表示程度深～硬、～直、～亮。又见bēng;běng。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绷"},{"id":"glyph-seal-7ef8","script":"seal","character":"绸","reading":"chóu","description":"捆缚\n通稠”。致密;稠密\n绸 chóu薄而软的丝织品～缎、红～。\n【绸缪】\n①缠绵情意～。\n②用绳索紧密缠捆。引申为修补未雨～。\n【绸舞】中国一种传统舞蹈。表演者手执彩绸舞动并配以各种步伐。多为单人表演，现也有集体表演。多用于传统戏曲民间舞蹈表演及其他喜庆场合。\n⒈绸子，一种薄而细软的丝织品～缎。纺～。\n绸tāo 1.缠裹;套。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绸"},{"id":"glyph-seal-7efa","script":"seal","character":"绺","reading":"liǔ","description":"丝缕编成的线\n一束理顺了的丝、线、须、毛发等\n绺子\n一绺子头发\n绺liǔ量词。常用于成束的丝、线、须、发等两～儿线。三～头发。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绺"},{"id":"glyph-seal-7efb","script":"seal","character":"绻","reading":"quǎn","description":"收缩\n缱绻。相结牢固,不离散。引申作眷恋","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绻"},{"id":"glyph-seal-7efc","script":"seal","character":"综","reading":"zōng；zeng","description":"织布机上使经线上下交错以受纬线的一种装置\n综光瓦亮\n灯光下,大理石的地板锃光瓦亮\n综亮\n皮鞋擦得锃亮\n总聚;总合\n⒈聚总，集合，组合～合。错～复杂。\n⒈织布机上使经线上下交错，便于纬线穿过的一种装置 。\n综zòng 1.织机上使经线上下交错以便梭子通过的装置。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-综"},{"id":"glyph-seal-7efe","script":"seal","character":"绾","reading":"wǎn","description":"盘绕,系结\n卷起\n系念;挂念\n控制\n总管\n奉阳君\n⒈系，盘结～个结。～头发。\n⒉卷把裤脚～起。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绾"},{"id":"glyph-seal-7eff","script":"seal","character":"绿","reading":"lǜ","description":"通菉”。一种野菜\n绿林\n绿林好汉\n绿林起义\n⒈一般草和树叶的颜色。\n②旧时指上山为匪，抢劫财物的集团。\n⒈像一般草或树叶的颜色，蓝和黄混合而成的颜色～叶。～水青山。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绿"},{"id":"glyph-seal-7f00","script":"seal","character":"缀","reading":"zhuì","description":"著作。组织文字以成篇章\n⒈缝，连结～合。～上。～补。～辞成文。\n⒉装饰点～。\n缀chuò 1.拘束。 2.牵制。 3.通\"辍\"。停;中止。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缀"},{"id":"glyph-seal-7f01","script":"seal","character":"缁","reading":"zī","description":"僧侣\n缁zī黑色穿～衣。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缁"},{"id":"glyph-seal-7f03","script":"seal","character":"缃","reading":"xiāng","description":"浅黄色\n浅黄色的帛\n树名\n缃 xiāng淡黄色。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缃"},{"id":"glyph-seal-7f04","script":"seal","character":"缄","reading":"jiān","description":"同本義\n古代用以固定棺木的绳索\n信件\n⒉书信～札。信～。\n⒊捆东西的绳索。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缄"},{"id":"glyph-seal-7f05","script":"seal","character":"缅","reading":"miǎn","description":"缅甸的简称\n遥远\n尽貌\n缅miǎn遥远～想。～怀故土。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缅"},{"id":"glyph-seal-7f07","script":"seal","character":"缇","reading":"tí","description":"缇tí橘红色，红黄色。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缇"},{"id":"glyph-seal-7f09","script":"seal","character":"缉","reading":"jī","description":"搜捕\n继续\n会合;和睦。通辑”\n适道已来,\n⒈捉拿，搜捕～拿。～获。～私。\n⒉见qī。\n⒈密针细缝法，一针对一针地缝～鞋口。\n⒉见jibh。\n缉jí 1.协调;和合。 2.收集;编辑。 3.编织;裁制。 4.理;整治。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缉"},{"id":"glyph-seal-7f0c","script":"seal","character":"缌","reading":"sī","description":"制作丧服的细麻布\n古代丧服名。五种丧服之最轻者,以细麻布为孝服,服丧三个月\n较为疏远的亲属关系\n缌sī细的麻布。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缌"},{"id":"glyph-seal-7f0e","script":"seal","character":"缎","reading":"duàn","description":"一种质地厚密而有光泽的丝织物\n缎 质地厚密、一面光滑的丝织品锦～。\n缎duàn 1.同\"?\"。贴于鞋跟的革片﹑丝绦之属。 2.一种质地厚密而有光泽的丝织物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缎"},{"id":"glyph-seal-7f11","script":"seal","character":"缑","reading":"gōu","description":"刀剑等柄上所缠的绳\n山名\n缑gōu缠在刀、剑等柄上的绳索，以免滑手。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缑"},{"id":"glyph-seal-7f12","script":"seal","character":"缒","reading":"zhuì","description":"拽;拉\n绳索\n缒zhuì用绳索拴住人或物从高处往下送将这些砖块从楼上～下去。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缒"},{"id":"glyph-seal-7f13","script":"seal","character":"缓","reading":"huǎn","description":"慢;不急迫。与急”相对\n柔软\n⒈慢，跟\"急\"相对～慢。～步。～急轻重。～ ～来迟。\n⒉迟，推迟～期。～办。～刑。～兵之计。\n⒊宽松，平和已～和。～冲地带。\n⒋苏醒，恢复他昏过去了，刚～过来。休息一会儿，～ ～气。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缓"},{"id":"glyph-seal-7f14","script":"seal","character":"缔","reading":"dì","description":"引申为郁结\n结合\n订立\n构造,建造\n约束;限制\n缔 dì结合；订立；～约。\n【缔约】订立条约。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缔"},{"id":"glyph-seal-7f15","script":"seal","character":"缕","reading":"lǚ；lv","description":"泛指细而长的东西,线状物\n⒈线千丝万～。\n⒉详尽地，一条一条地～陈。～析。\n⒊量词两～麻线。三～炊烟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缕"},{"id":"glyph-seal-7f16","script":"seal","character":"编","reading":"biān","description":"交织,编结\n编辑;创作\n①把细长条状物交叉地组织起来～花篮。\n②按一定的顺序组织排列～号、～班。\n⑤捏造～造谎言。\n⑥成本的书人手一～。\n⑦书籍按内容划分的单位上～、下～。\n【编队】\n①将人群或运输工具等编成一定的队形。\n【编户】编入户籍的平民。中国古代自商鞅变法开始，历代均把平民编入政府户籍，称编户。\n【编磬】古代打击乐器。由16块石制或玉制的磬组成。用小木槌击奏。周代以来用于雅乐。\n机器执行，必须将它译成机器语言程序。\n【编译员】带有编辑性质的翻译人员。\n【编钟】古代打击乐器。把一系列铜制的钟挂在木架上组成，用小木槌击奏。各时代形状大小不一，枚数也不相同。\n【编撰】编辑；编写。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-编"},{"id":"glyph-seal-7f18","script":"seal","character":"缘","reading":"yuán","description":"器物的边沿\n原故,理由\n因缘;缘分\n言谈大自缘。\n画与建\n⒈边边～。外～。\n⒉沿着，顺着～溪行。\n⒊遵循，依照～法而治。\n⒋爬，攀附～木而上。攀～。夤～。\n⒌人与人的关系人～。血～。\n⒍宿命论者指人与人或人与事所谓\"命中注定的遇合机会\"～分、有～、机～等等不过是自圆其说。\n⒎因为，因由～故。～由。～何至此？\n缘yuàn 1.衣服边上的镶绲;衣服的边。 2.给衣履等物镶边或绲边。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缘"},{"id":"glyph-seal-7f19","script":"seal","character":"缙","reading":"jìn","description":"缙绅\n束在衣服外面的大带子\n缙绅大\n缙jìn〈古〉\n⒈赤色的丝织物。\n⒉同\"jìn搢\n⒉\"～绅。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缙"},{"id":"glyph-seal-7f1a","script":"seal","character":"缚","reading":"fù","description":"约束;限制\n绳索\n量词。用\n缚 fù缠束，捆绑束～。～鸡。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缚"},{"id":"glyph-seal-7f1b","script":"seal","character":"缛","reading":"rù","description":"通褥”。褥子\n繁多\n烦琐;对…阐述过详\n⒉〈古〉通\"褥\"。褥子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缛"},{"id":"glyph-seal-7f1d","script":"seal","character":"缝","reading":"féng","description":"补合\n缝合处\n缝 féng用针线连缀～补。\n【缝纫】剪裁制做服装。\n⒈裂开的或自然显露的窄长口子一条裂～。有道～隙。墙上有～。\n⒉接合的地方无～钢管。这是～合口留下的痕迹。\n⒊空子～隙。见～插针。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缝"},{"id":"glyph-seal-7f1f","script":"seal","character":"缟","reading":"gǎo","description":"缟gǎo白色的生丝绢。也指白色。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缟"},{"id":"glyph-seal-7f20","script":"seal","character":"缠","reading":"chán","description":"纠缠;搅扰\n应付;对付\n①缠绕～脚。\n②纠缠；搅扰你不要再来～我了，我正忙着呢！\n③应付。\n②委婉动人曲调～。\n【缠头】古代歌舞的人把锦帛缠在头上作装饰，叫'缠头'。又指赠送给歌舞者的锦帛或财物。\n⒈盘绕，扎束～绕。～绷带。\n⒉搅扰，牵绊纠～。有事～着。\n⒊〈方〉应付跟这种人难～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缠"},{"id":"glyph-seal-7f21","script":"seal","character":"缡","reading":"lí","description":"用丝装饰鞋头\n古时妇女系在身前的大佩巾\n带子","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缡"},{"id":"glyph-seal-7f22","script":"seal","character":"缢","reading":"yì","description":"用绳子勒颈绝气而死\n缢加别械。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缢"},{"id":"glyph-seal-7f23","script":"seal","character":"缣","reading":"jiān","description":"用缣做的衣服\n缣jiān细密的绢。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缣"},{"id":"glyph-seal-7f25","script":"seal","character":"缥","reading":"piāo","description":"同飘”。飞扬\n缥缈，缥乎，缥缥\n缥piǎo青白色，淡青色。也指青白色的丝织品。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缥"},{"id":"glyph-seal-7f26","script":"seal","character":"缦","reading":"màn","description":"帷幔;帏幕\n同慢”,宽缓;惰慢\n注教\n缦màn没有花纹的丝织品～帛。泛指没有花纹的～车。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缦"},{"id":"glyph-seal-7f28","script":"seal","character":"缨","reading":"yīng","description":"彩带,古代女子许嫁时所佩\n套马的革带,驾车用。引申指绳索\n⒈线、绳、彩带等做的装饰品彩灯～子§～枪。慷慨泪沾～。\n⒉像缨的东西萝卜～儿。蒜苗～子。\n⒊长带，拘捆人的绳子长～在手。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缨"},{"id":"glyph-seal-7f29","script":"seal","character":"缩","reading":"suō","description":"收缩\n⒈用绳子捆起来。\n⒉退～回。退～。\n⒊蜷，收敛收～。畏～。～手～脚。\n⒋减少，变小，变短压～。紧～。～减。～小。～短。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缩"},{"id":"glyph-seal-7f2a","script":"seal","character":"缪","reading":"miù","description":"纰缪;错误\n通穆”。穆然,静思\n通穆”。虔诚\n诈伪\n通樛”。绞结\n⒈姓。\n⒈通\"谬\"。错误纰～。\n⒉假装～为恭敬。\n缪jiū 1.通\"樛\"。绞结。 2.通\"纠\"。\n缪mù 1.古时宗庙所列次序，父子辈递为昭穆，左为昭，右为穆。 2.调和;和悦。 3.虔诚貌。参见\"缪卜\"。\n缪liáo 1.缠绕。\n缪lù 1.并;合。参见\"缪力同心\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缪"},{"id":"glyph-seal-7f2b","script":"seal","character":"缫","reading":"sāo","description":"煮茧抽丝\n通藻”。文彩;修饰\n纑”\n缫丝\n缫丝厂\n缫丝机\n缫sāo将蚕茧放在滚水里抽丝～丝。\n缫zǎo 1.通\"藻\"。五彩丝绳。 2.同\"璪\"。玉器的彩色垫板。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缫"},{"id":"glyph-seal-7f2d","script":"seal","character":"缭","reading":"liáo","description":"围绕;绕道而行\n⒈缠绕，纷乱～绕。眼花～乱。〈引〉环绕～以周墙。\n⒉用针线缝缀～缝儿。～衣边。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缭"},{"id":"glyph-seal-7f2e","script":"seal","character":"缮","reading":"shàn","description":"制造;整治\n工整地抄写\n然后\n⒈修补，整治修～。～治。\n⒉抄写～写文稿。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缮"},{"id":"glyph-seal-7f2f","script":"seal","character":"缯","reading":"zēng","description":"通砫”。古代射鸟用的箭\n好弋者先具缴\n缯zēng〈古〉丝织品的统称。\n缯zèng〈古〉捆，扎～起来。～紧些。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缯"},{"id":"glyph-seal-7f30","script":"seal","character":"缰","reading":"jiāng","description":"马缰绳\n缰绳","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缰"},{"id":"glyph-seal-7f31","script":"seal","character":"缱","reading":"qiǎn","description":"紧束;牵住\n用同纤”。拉船用的绳索\n缱绻","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缱"},{"id":"glyph-seal-7f32","script":"seal","character":"缲","reading":"qiāo","description":"缝纫方法,做衣服边或带子时把布边儿往里头卷进去,然后藏着针脚缝\n缲sāo将蚕茧放在滚水里抽丝～丝。\n⒈一种缝纫法，将布边卷在里面缝，使不露针脚～边。～带子。\n缲zǎo 1.深青带红色之帛。 2.冕旒的绳子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缲"},{"id":"glyph-seal-7f33","script":"seal","character":"缳","reading":"huán","description":"绳圈;绞索\n以绳索相系绕。即网络\n⒈旗上的系结。\n⒊绞杀～首。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缳"},{"id":"glyph-seal-7f35","script":"seal","character":"缵","reading":"zuǎn","description":"用同纂”。撰写\n缵zuǎn继续，继承。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缵"},{"id":"glyph-seal-7f36","script":"seal","character":"缶","reading":"fǒu","description":"fǒu：古代一种大肚子小口儿的盛酒瓦器。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缶"},{"id":"glyph-seal-7f38","script":"seal","character":"缸","reading":"gāng","description":"gāng：(1)盛东西的器物，圆筒状，底小口大。用陶、瓷、玻璃等制成水～。～子。\n(2)用砂子、陶土等混合而成的一种质料～瓦。～盆。\n(3)像缸的器物汽～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缸"},{"id":"glyph-seal-7f3a","script":"seal","character":"缺","reading":"quē","description":"quē：(1)不够～乏。～少。～憾。欠～。～漏。\n(2)残破～点。～口。～陷。\n(3)空额（指职位）～额。补～。\n(4)该到而未到～勤。～席。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缺"},{"id":"glyph-seal-7f42","script":"seal","character":"罂","reading":"yīng","description":"大腹小口的瓦器。或作畂”\n泛指小口大腹的瓶\n植物名\n罂粟\n⒈小口大腹的瓶子。\n，需经高级医师处方，慎重使用。果壳叫\"罂粟壳\"，也可供药用。私种罂粟，吸食鸦片类毒品以及制毒、贩毒等，均违法，要受到严惩。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罂"},{"id":"glyph-seal-7f44","script":"seal","character":"罄","reading":"qìng","description":"qìng：(1)本义为器中空，引申为尽，用尽告～。～其所有。～竹难书。\n(2)古同磬”，打击乐器。\n(3)显现夫犬马，人所知也，旦暮～于前”。\n(4)严整的样子师旷～然”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罄"},{"id":"glyph-seal-7f45","script":"seal","character":"罅","reading":"xià","description":"xià：缝隙，裂缝云～。石～。～缝。～隙。～漏（缝隙，喻事情的漏洞）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罅"},{"id":"glyph-seal-7f50","script":"seal","character":"罐","reading":"guàn","description":"guàn：盛东西或汲水用的瓦器，亦泛指各种圆筒形的盛物器皿瓦～。铁～。～头。拔火～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罐"},{"id":"glyph-seal-7f51","script":"seal","character":"网","reading":"wǎng","description":"泛指多孔而状如网的东西\n喻指法律,\n⒈用绳线结成的渔猎工具撒～。设～。鱼～。\n⒉形状像网的～兜。蛛～。钢丝～。\n⒊用网捕捉～鸟。～着了大鱼。\n⒋像网那样的组织或系统通讯～。铁路～。\n①渔猎用的网。\n②搜求，设法招致～罗英才。有时含贬义～罗党羽。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-网"},{"id":"glyph-seal-7f54","script":"seal","character":"罔","reading":"wǎng","description":"wǎng：(1)蒙蔽，诬～民（陷害人民）。～己（受人诳骗）。欺～。\n(2)无，没有～极（a.没有定准，变化无常；b.无穷，久远）。置若～闻。\n(3)古同惘”，失意。\n(4)古同网”，用绳线等结成的捕鱼捉鸟器具。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罔"},{"id":"glyph-seal-7f55","script":"seal","character":"罕","reading":"hǎn","description":"hǎn：(1)稀少稀～。～见。～俦（很少与之相比的）。～世之宝。人迹～至。\n(2)古代称捕鸟用的长柄小网。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罕"},{"id":"glyph-seal-7f57","script":"seal","character":"罗","reading":"luó","description":"轻软的丝织品\n⒈捕鸟的网～网。\n⒉张网捕捉～雀。\n⒊招请，搜集～致。收～。～天下之士。\n⒋排列，散布～列。星～棋布。\n⒌稀疏而轻软的丝织品～衫。～扇。\n⒍一种细密的筛子绢～。铜丝～。\n⒎用罗筛东西～面。\n⒐同\"脶\"。手指纹。\n罗luo 1.语气词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罗"},{"id":"glyph-seal-7f5a","script":"seal","character":"罚","reading":"fá","description":"对违反规定或有过失者给予惩处，如处罚、罚款。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-7f5f","script":"seal","character":"罟","reading":"gǔ","description":"gǔ：(1)鱼网是犹无鱼而为鱼～也。”\n(2)指法网岂不怀归？畏此罪～。”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罟"},{"id":"glyph-seal-7f62","script":"seal","character":"罢","reading":"bà","description":"遣返,遣归\n停止\n①中止某种活动～课、～工。\n②免去；解除～免。\n【罢黜】\n①贬低并排斥～百家。\n【罢论】不必再论说；不必再论说的事此事已成～。\n罢pí 1.疲劳;衰弱。 2.疲敝;惫乏。 3.慰劳。 4.弱;无能。 5.无行。参见\"罢士\"﹑\"罢女\"。 6.败，失败。\n罢bǐ 1.离散;分散;散开。\n罢pì 1.见\"罢辜\"。\n罢bǎi 1.见\"郎罢\"。\n罢ba 1.语气词。同\"吧\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罢"},{"id":"glyph-seal-7f68","script":"seal","character":"罨","reading":"yǎn","description":"yǎn：(1)捕鸟或捕鸟的网，亦指用罨捕取。\n(2)覆盖，掩盖热～法（热敷法）。冷～法（冷敷法）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罨"},{"id":"glyph-seal-7f69","script":"seal","character":"罩","reading":"zhào","description":"zhào：(1)覆盖，覆盖物体的东西笼～。灯～。～衣。\n(2)捕鱼或养鸡鸭等用的竹笼子鸡～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罩"},{"id":"glyph-seal-7f6a","script":"seal","character":"罪","reading":"zuì","description":"zuì：(1)犯法的行为犯～。～人。认～。有～。～恶。～名。～魁。～行。～证。～责。～孽（迷信的人认为应受到报应的罪恶）。～不容诛。\n(2)过失，把过失归到某人身上功～。～愆。～尤（尤”，过失，罪过）。归～于人。\n(3)刑罚判～。畏～。待～。请～。\n(4)苦难，痛苦受～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罪"},{"id":"glyph-seal-7f6e","script":"seal","character":"置","reading":"zhì","description":"zhì：(1)放，摆，搁安～。布～。～放。～身。位～。～信。～评。～疑。～辩。推心～腹。～若罔闻。～之度外。\n(2)设立，设备装～。设～。\n(3)购买添～。～办。～备。～买。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-置"},{"id":"glyph-seal-7f72","script":"seal","character":"署","reading":"shǔ","description":"shǔ：(1)办理公务的机关专～。公～。官～。\n(2)布置部～。\n(3)签名，题字签～。～名。～字。\n(4)暂代～理。兼～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-署"},{"id":"glyph-seal-7f74","script":"seal","character":"罴","reading":"pí","description":"棕熊","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罴"},{"id":"glyph-seal-7f79","script":"seal","character":"罹","reading":"lí","description":"lí：(1)遭受苦难或不幸～厄。～病。～祸。～难（nàn）。\n(2)忧患；苦难逢此百～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罹"},{"id":"glyph-seal-7f7d","script":"seal","character":"罽","reading":"jì","description":"古代用毛织成的毡、毯一类织物。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-7f7e","script":"seal","character":"罾","reading":"zēng","description":"zēng：(1)古代一种用木棍或竹竿做支架的方形鱼网。\n(2)网起乃丹书帛曰‘陈胜王’，置人所～鱼腹中”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罾"},{"id":"glyph-seal-7f81","script":"seal","character":"羁","reading":"jī","description":"古代女孩留在头顶像马络头一般的头发\n套上笼头\n⒈马笼头白马饰金～。〈引〉拘束，束缚～绊。放荡不～。\n⒉停留～留。\n⒊寄居在外，寄居在外的人或外乡人～旅。弃亲用～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羁"},{"id":"glyph-seal-7f8a","script":"seal","character":"羊","reading":"yáng；xiáng","description":"yáng：(1)哺乳动物，反刍类，一般头上有一对角，品种很多绵～。黄～。羚～。～羔。～毫。～肠线。～肠小道。\n(2)姓。\nxiáng：古同祥”，吉祥。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羊"},{"id":"glyph-seal-7f8c","script":"seal","character":"羌","reading":"qiāng","description":"qiāng：(1)中国古代西部的民族～笛。\n(2)中国少数民族，主要分布于四川省～族。\n(3)文言助词，用在句首，无义～内恕己以量人兮，各兴心而嫉妒”。\n(4)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羌"},{"id":"glyph-seal-7f8e","script":"seal","character":"美","reading":"měi","description":"měi：(1)好，善～德。～学。～谈。审～。～丽。～容（美化容貌）。～不胜收。\n(2)得意，高兴～滋滋的。\n(3)称赞，以为好赞～。～言。～誉。\n(4)指亚美利加洲”（简称美洲”）北～。南～。\n(5)指美国”～元。～籍华人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-美"},{"id":"glyph-seal-7f91","script":"seal","character":"羑","reading":"yǒu","description":"yǒu：诱导。\n〔～里〕古地名，在今中国河南省汤阴县北。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羑"},{"id":"glyph-seal-7f94","script":"seal","character":"羔","reading":"gāo","description":"gāo：(1)小羊羊～。～羊。～儿皮。\n(2)泛指动物的幼崽儿鹿～儿。牛～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羔"},{"id":"glyph-seal-7f9e","script":"seal","character":"羞","reading":"xiū","description":"xiū：(1)感到耻辱～耻。～辱。～恶。\n(2)难为情，害臊害～。～惭。～臊（sào）。～愧‖～。～赧（因害臊而红了脸的样子）。～怯。～涩。\n(3)使难为情～人。你别～我。\n(4)进献～玉芝以疗饥”。\n(5)同馐”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羞"},{"id":"glyph-seal-7f9f","script":"seal","character":"羟","reading":"qiǎng","description":"羟基\n羟qiān 1.羊名。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羟"},{"id":"glyph-seal-7fa1","script":"seal","character":"羡","reading":"xiàn","description":"xiàn：(1)因喜爱而希望得到贪～。～慕。～妒。艳～。临渊～鱼。\n(2)有余，余剩余～。以～补不足”。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羡"},{"id":"glyph-seal-7fa4","script":"seal","character":"群","reading":"qún","description":"qún：(1)相聚成伙的，聚集在一起的～岛。～山。～书。～芳。～居。～落（luò）。～集。～雕。～蚁附膻（许多蚂蚁附着在有膻味的东西上；喻臭味相投的人趋炎附势，追逐私利）。\n(2)众人～众。～情。～雄。～策～力。～威～胆。\n(3)量词，用于成群的人或物一～孩子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-群"},{"id":"glyph-seal-7faf","script":"seal","character":"羯","reading":"jié","description":"jié：(1)公羊，特指骟过的～羊。摩～。\n(2)中国古代北方的民族，匈奴的一个分支～族。～鼓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羯"},{"id":"glyph-seal-7fb2","script":"seal","character":"羲","reading":"xī","description":"xī：姓。\n〔伏～〕中国神话中人类的始祖，和女祸”、神农”并称太古的三皇。简称羲”，如～皇”，～炎”（伏羲和炎帝。炎帝即神农），～轩”（伏羲和轩辕），～黄”（伏羲和黄帝），～经”（即《易经》，传说《易经》八卦为伏羲所作），～文”（伏羲和文王，传说伏羲画八卦，文王作卦辞）。\n〔～和〕a.羲氏”、和氏”，传说中掌天文历法的官吏；b.神话中驾日车的神；c.神话中太阳的母亲；d.中国汉代王莽时所设官名。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羲"},{"id":"glyph-seal-7fb8","script":"seal","character":"羸","reading":"léi","description":"léi：瘦弱～瘦。～困（瘦弱困顿）。～顿。～弱。～惫。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羸"},{"id":"glyph-seal-7fb9","script":"seal","character":"羹","reading":"gēng","description":"gēng：用蒸煮等方法做成的糊状、冻状食物～汤。肉～。鸡蛋～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羹"},{"id":"glyph-seal-7fbc","script":"seal","character":"羼","reading":"chàn","description":"chàn：搀杂～入。～杂。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羼"},{"id":"glyph-seal-7fbd","script":"seal","character":"羽","reading":"yǔ","description":"yǔ：(1)鸟的毛～毛。～绒。～书。～衣。～扇。～族（指鸟类）。～旗。～檄（羽书）。\n(2)鱼类或昆虫的翅膀，道教传说中指会飞的仙人～翼。～翰（翅膀）。～士（a.会飞的仙人；b.道士）。\n(3)箭上的羽毛，借指箭～猎。\n(4)古代五音之一，相当于简谱6”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羽"},{"id":"glyph-seal-7fbf","script":"seal","character":"羿","reading":"yì","description":"yì：(1)古人名，传说是中国夏代有穷国的君主，善于射箭。亦称后羿”、夷羿”。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羿"},{"id":"glyph-seal-7fc1","script":"seal","character":"翁","reading":"wēng","description":"wēng：(1)老头儿老～。渔～。塞～失马，焉知非福”。\n(2)父亲家祭无忘告乃～”。\n(3)丈夫的父亲～姑（公婆）。\n(4)妻子的父亲～婿。\n(5)姓。\n(6)鸟颈毛。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翁"},{"id":"glyph-seal-7fc5","script":"seal","character":"翅","reading":"chì","description":"chì：(1)鸟和昆虫等用来飞行的器官～膀。～翼。插～难飞。\n(2)翘出像翅的东西～果。纱帽～。\n(3)古同啻”，但，只。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翅"},{"id":"glyph-seal-7fca","script":"seal","character":"翊","reading":"yì","description":"yì：(1)辅佐，帮助～戴（辅佐拥戴）。～赞。\n(2)古同翌”，明日。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翊"},{"id":"glyph-seal-7fce","script":"seal","character":"翎","reading":"líng","description":"líng：鸟翅和尾上的长而硬的羽毛雁～。野鸡～。孔雀～。～毛。～扇。～子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翎"},{"id":"glyph-seal-7fd4","script":"seal","character":"翔","reading":"xiáng","description":"xiáng：盘旋地飞而不扇动翅膀滑～。翱～。\n〔～实〕详细而确实。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翔"},{"id":"glyph-seal-7fd5","script":"seal","character":"翕","reading":"xī","description":"xī：(1)合，聚，和顺～动。～张（一合一开）。兄弟既～，和乐且湛。\n(2)鸟类躯部背面和两翼表面的总称。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翕"},{"id":"glyph-seal-7fd8","script":"seal","character":"翘","reading":"qiào","description":"鸟尾\n泛指动物的尾部\n抬起\n⒈鸟尾巴上的长毛。\n⒉举起，抬起，向上～望。～足。～首。\n⒊板状物因由湿变干而引起弯曲不平柜子晒～了。门板～棱了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翘"},{"id":"glyph-seal-7fda","script":"seal","character":"翚","reading":"huī","description":"翚huī 1.五彩山雉。 2.疾飞。 3.山雉的羽毛。亦泛指羽毛。 4.通\"挥\"。挥动。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翚"},{"id":"glyph-seal-7fdf","script":"seal","character":"翟","reading":"zhái；dí","description":"dí：(1)长尾山雉（野鸡）。\n(2)古代乐舞用的雉羽。\n(3)古同狄”，称中国北方的民族。\nzhái：姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翟"},{"id":"glyph-seal-7fe0","script":"seal","character":"翠","reading":"cuì","description":"cuì：(1)绿色～绿。苍～。～微（青绿的山色，亦泛指青山）。\n(2)指翡翠”（硬玉）～玉。～镯。珠宝～钻。\n〔～鸟〕属鸣禽类，形似杜鹃，嘴长，头部深橄榄色，有青绿色斑纹，背青绿色，腹赤褐色，尾短，捕食小鱼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翠"},{"id":"glyph-seal-7fe1","script":"seal","character":"翡","reading":"fěi","description":"fěi：古书上指一种有红毛的鸟。\n〔～翠〕a.鸟的一属，有蓝、绿色羽毛，生活在水边，羽毛可做装饰品；b.矿物，绿色、蓝绿色或白色中带绿色斑纹，半透明，有光泽，可做装饰品，亦称硬玉”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翡"},{"id":"glyph-seal-7fe5","script":"seal","character":"翥","reading":"zhù","description":"zhù：鸟向上飞轩～。龙翔凤～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翥"},{"id":"glyph-seal-7fe9","script":"seal","character":"翩","reading":"piān","description":"piān：(1)很快地飞。\n(2)轻快，飘忽～然。～跹。～～。～若惊鸿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翩"},{"id":"glyph-seal-7fee","script":"seal","character":"翮","reading":"hé","description":"hé：(1)鸟翎的茎，翎管。\n(2)鸟的翅膀举～。振～高飞。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翮"},{"id":"glyph-seal-7ff0","script":"seal","character":"翰","reading":"hàn","description":"hàn：(1)长而坚硬的羽毛理翩振～。\n(2)借指毛笔和文字、书信等～苑。～墨（笔墨，借指诗文书画）。～藻。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翰"},{"id":"glyph-seal-7ff1","script":"seal","character":"翱","reading":"áo","description":"áo：〔～翔〕展开翅膀在天空回旋地飞，如雄鹰在天空～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翱"},{"id":"glyph-seal-7ff3","script":"seal","character":"翳","reading":"yì","description":"yì：(1)用羽毛做的华盖。\n(2)遮蔽，障蔽荫～。～蔽。～障。～然。\n(3)掩蔽物兵不解～”。\n(4)眼角膜上所生障碍视线的白斑白～。\n(5)古同殪”，树木枯死，倒伏于地。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翳"},{"id":"glyph-seal-7ffb","script":"seal","character":"翻","reading":"fān","description":"fān：(1)歪倒（dǎo），反转，变动位置，改变推～。～车。～卷。～滚。～腾。～工。～阅。～身。～地。～修。～建。～改。～脸。人仰马～。～江倒海（形容水势浩大，多喻力量或气势非常壮大）。～云覆雨（喻反覆无常或玩弄手段）。\n(2)数量成倍的增加～番。\n(3)越过～越。\n(4)飞。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翻"},{"id":"glyph-seal-7ffc","script":"seal","character":"翼","reading":"yì","description":"yì：(1)翅膀～翅。比～双飞。卵～。羽～。～护。～蔽。\n(2)左右两侧中的一侧左～。侧～。\n(3)帮助，辅佐～助。\n(4)古同翌”，明天，明年。\n(5)星名，二十八宿之一。\n(6)姓。\n〔～～〕a.谨慎，如小心～～”；b.严整有秩序；c.繁盛，众多。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翼"},{"id":"glyph-seal-8000","script":"seal","character":"耀","reading":"yào","description":"yào：(1)光线照射～眼。闪～。照～。光～。～斑。\n(2)显扬，显示出来夸～。炫～。～武扬威。\n(3)光荣荣～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耀"},{"id":"glyph-seal-8001","script":"seal","character":"老","reading":"lǎo","description":"lǎo：(1)年纪大，时间长，有经验，陈旧的～当益壮。～朋友。～练。～化。少年～成。～马识途。\n(2)对年纪大的人的尊称吴～。～人家。～大爷。\n(3)极，很～早。～羞成怒。\n(4)老年人敬～院。扶～携幼。～有所为（wéi）。\n(5)晚年～年。～境。\n(6)敬老，养老～吾老，以及人之老。”\n(7)总是，经常～是生病。\n(8)原来的～地方。\n(9)与嫩”相对黄瓜长～了。\n(10)词头，用于表排行，用于表相互尊称，或加在某些动植物名前构成多音节词～大。～鹰。～倭瓜。\n(11)老子（中国先秦思想家）及其学说的简称。\n(12)死的讳称～了。\n(13)姓。\n〔～板〕指业主或企业的经营者。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-老"},{"id":"glyph-seal-8003","script":"seal","character":"考","reading":"kǎo","description":"kǎo：(1)试验，测验～试。～查。\n(2)检查，查核～察。～勤。稽～。～核。\n(3)推求，研究～古。～据。～订。～证。\n(4)老，年纪大寿～。\n(5)原指父亲，后多指已死的父亲先～。如丧～妣。\n(6)击，敲而陋者乃以斧斤～击而求之，自以为得其实”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-考"}];
